package com.retailflow.pos.reports;
import com.retailflow.pos.expense.*;import com.retailflow.pos.product.ProductRepository;import com.retailflow.pos.purchasebill.*;import com.retailflow.pos.sales.*;import java.math.BigDecimal;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;
@Service public class ReportService{
 private final InvoiceRepository sales;private final PurchaseBillRepository bills;private final ExpenseRepository expenses;private final ProductRepository products;
 public ReportService(InvoiceRepository sales,PurchaseBillRepository bills,ExpenseRepository expenses,ProductRepository products){this.sales=sales;this.bills=bills;this.expenses=expenses;this.products=products;}
 public Map<String,Object>pnl(LocalDate from,LocalDate to){var inv=sales.findByInvoiceDateBetween(from.atStartOfDay(),to.plusDays(1).atStartOfDay().minusNanos(1));var gross=inv.stream().filter(i->i.getStatus()==Invoice.Status.COMPLETED).map(Invoice::getTotal).reduce(BigDecimal.ZERO,BigDecimal::add);var returns=inv.stream().filter(i->i.getStatus()==Invoice.Status.REFUNDED).map(Invoice::getTotal).reduce(BigDecimal.ZERO,BigDecimal::add);var purchases=bills.findByBillDateBetween(from,to).stream().filter(b->b.getStatus()!=PurchaseBill.Status.DRAFT).map(PurchaseBill::getGrandTotal).reduce(BigDecimal.ZERO,BigDecimal::add);var exp=expenses.findByExpenseDateBetween(from,to).stream().map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);var closing=products.findAll().stream().map(p->p.getStock().multiply(p.getCostPrice())).reduce(BigDecimal.ZERO,BigDecimal::add);return Map.of("grossRevenue",gross,"returnsValue",returns,"purchasesValue",purchases,"expenses",exp,"closingStock",closing,"netProfit",gross.subtract(returns).subtract(purchases).subtract(exp).add(closing));}
 public Map<String,Object>gst(LocalDate from,LocalDate to){var output=sales.findByInvoiceDateBetween(from.atStartOfDay(),to.plusDays(1).atStartOfDay().minusNanos(1)).stream().map(Invoice::getGstAmount).reduce(BigDecimal.ZERO,BigDecimal::add);var input=bills.findByBillDateBetween(from,to).stream().map(PurchaseBill::getTotalGst).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);return Map.of("outputGst",output,"inputGst",input,"netPayable",output.subtract(input));}
}
